class Solution:
    def sortJumbled(self, mapping: list[int], nums: list[int]) -> list[int]:
        def mapped_value(n: int) -> int:
            if n == 0:
                return mapping[0]
            result = 0
            place = 1
            while n > 0:
                result += mapping[n % 10] * place
                n //= 10
                place *= 10
            return result
        return sorted(nums, key=mapped_value)

